'use strict';
const baseTimeline=renderers.timeline,baseTrends=renderers.trends,baseSettings=renderers.settings,baseOverview=renderers.overview;
function ensureExtras(){state.wellness??=[];state.movements??=[];state.contractions??=[];state.postpartumLogs??=[];if(!state.bag)state.bag=['Medical notes and ID','Phone and charger','Comfortable clothes','Toiletries','Maternity pads','Baby clothes and nappies'].map((text,i)=>({id:'bag-'+i,text,done:false}));state.birthPlan??={};state.mode??='pregnancy';state.notificationEnabled??=false;}
ensureExtras();
const addedRoutes=[['wellness','Daily wellbeing'],['growth','Baby development'],['birth','Birth preparation'],['food','Food & safety'],['movement','Movement journal'],['contractions','Contraction timer'],['postpartum','After birth'],['reminders','Calendar & alerts']];routes.splice(4,0,...addedRoutes);$('#nav').innerHTML=routes.map(([r,n])=>`<a href="#${r}">${n}</a>`).join('');
const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dayNumber=s=>{let [y,m,d]=s.split('-').map(Number);return Date.UTC(y,m-1,d)/86400000};
function pregnancyDays(){return state.profile.due?280-(dayNumber(state.profile.due)-dayNumber(today())):null}
function countdown(){let d=pregnancyDays();if(d===null)return '<p>Add your due date in Profile to see your countdown.</p>';let left=280-d;return `<div class="big">${Math.abs(left)} days</div><p>${left>=0?'until your expected due date':'past your expected due date'} · ${d>=0?`${Math.floor(d/7)} weeks + ${d%7} days`:'Pregnancy dates are in the future'}</p><span class="tag">${d<0?'Check dates':d<91?'First trimester':d<196?'Second trimester':'Third trimester'}</span><p class="muted">Due dates are estimates, not a scheduled birth date.</p>`}
renderers.overview=()=>{ensureExtras();return (state.mode==='postpartum'?heading('Your postpartum journey','Your pregnancy history stays with you.')+card('After birth','<p>Track recovery, sleep, mood, and your baby’s daily routine.</p><a class="button" href="#postpartum">Open postpartum journal</a>'):baseOverview())+`<div class="grid">${state.mode==='postpartum'?'':card('Your countdown',countdown())}${card('Make space for yourself','<p>Record mood, sleep, weight, and water intake in one daily check-in.</p><a class="button" href="#wellness">Add today’s check-in</a>')}</div>`};
renderers.timeline=()=>baseTimeline()+`<div class="grid">${card('Due date countdown',countdown())}${card('Explore development','<p>Browse typical development by week, with source links and size comparisons.</p><a class="button" href="#growth">Browse weekly guide</a>')}</div>`;
renderers.trends=()=>baseTrends()+card('More daily tracking','<p>Your mood, sleep, water, and weight logs have their own journal.</p><a class="button" href="#wellness">Open daily wellbeing</a>');
renderers.settings=()=>baseSettings()+card('Pregnancy or postpartum',`<p>Switch modes without losing your history. Pregnancy risk predictions do not apply to postpartum health.</p><div class="actions"><button data-mode="pregnancy" class="${state.mode==='pregnancy'?'':'secondary'}">Pregnancy mode</button><button data-mode="postpartum" class="${state.mode==='postpartum'?'':'secondary'}">Postpartum mode</button></div>`);
const selectField=(name,label,options,value='')=>`<div><label for="${name}">${label}</label><select id="${name}" name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;
function numberSummary(k,unit){let a=state.wellness.filter(x=>x[k]!==''&&Number.isFinite(Number(x[k]))).slice(-7);return a.length?`${(a.reduce((n,x)=>n+Number(x[k]),0)/a.length).toFixed(1)} ${unit}`:'—'}
renderers.wellness=()=>{ensureExtras();return heading('Daily wellbeing','Your personal journal. These entries do not change the risk model.')+`<div class="grid stats">${card('Recent sleep average',`<div class="big">${numberSummary('sleep','h')}</div><small>Last 7 recorded check-ins</small>`)}${card('Recent water average',`<div class="big">${numberSummary('water','mL')}</div><small>Last 7 recorded check-ins · no prescribed target</small>`)}${card('Latest mood',`<div class="big">${esc(state.wellness.at(-1)?.mood||'—')}</div>`)}</div><div class="grid">${card('Daily check-in',form('wellnessForm',`<div class="grid">${field('day','Date','date',today(),'required max="'+today()+'"')}${selectField('mood','Mood',['Okay','Good','Low','Anxious','Mixed'])}${field('sleep','Sleep · hours','number','','min="0" max="24" step="0.1"')}${field('weight','Weight · kg','number','','min="1" max="400" step="0.1"')}${field('water','Water · mL','number','','min="0" max="20000" step="50"')}</div><p><label for="wellnote">Notes</label><textarea name="note" id="wellnote" maxlength="2000"></textarea></p><p class="muted">One entry per day; saving the same date updates it.</p>`,'Save check-in'))}${card('Your check-ins',state.wellness.slice().sort((a,b)=>b.day.localeCompare(a.day)).map(x=>`<div class="row"><div><b>${esc(x.day)} · ${esc(x.mood)}</b><p class="muted">Sleep ${esc(x.sleep||'—')} h · Weight ${esc(x.weight||'—')} kg · Water ${esc(x.water||'—')} mL</p><p>${esc(x.note)}</p></div><button class="danger" data-delete="wellness" data-id="${x.id}">Delete</button></div>`).join('')||empty('No daily check-ins yet.'))}</div>`};
let weekly=[];let selectedWeek=Math.min(41,Math.max(4,gestation()||12));
const development={12:'Organs and muscles have developed; the skeleton is beginning to harden into bone.',20:'A protective coating called vernix covers the skin. Sucking and movement skills are developing.',28:'The heart continues beating faster than an adult heart; its rate changes throughout development.',36:'Lungs and feeding abilities are maturing in preparation for life after birth.'};
function growthCard(w){let r=weekly.find(x=>x.week===w);if(!r)return empty('Loading the weekly guide. If offline, revisit after an online visit.');let exact=development[w];return `<span class="eyebrow">TYPICAL DEVELOPMENT · WEEK ${w}</span><div class="big">${r.comparison?esc(r.comparison):'Growing week by week'}</div>${r.length?`<p>Approximate length: <b>${r.length} cm</b> · ${esc(r.basis)}</p>`:''}<p>${exact|| (r.excerpt?'NHS excerpt: “'+esc(r.excerpt)+'…”':'Explore this week’s developmental changes in the linked NHS guide.')}</p><p class="muted">These are reference estimates, not the size or health of your own baby. Length measurement methods change during pregnancy. No individual growth assessment is made.</p><a class="button" href="${esc(r.url)}" target="_blank" rel="noopener">Read week ${w} on NHS</a><small class="source-note">Source: NHS Best Start in Life · checked 10 October 2026</small>`}
renderers.growth=()=>heading('Baby development','Browse weeks 4–41. Typical size comparisons help explain development.')+card('Choose a week',`<label for="growthWeek">Pregnancy week</label><select id="growthWeek">${Array.from({length:38},(_,i)=>i+4).map(w=>`<option value="${w}" ${w===selectedWeek?'selected':''}>Week ${w}</option>`).join('')}</select><div id="growthDetail" class="growth-detail">${growthCard(selectedWeek)}</div>`);
renderers.birth=()=>{ensureExtras();let p=state.birthPlan;return heading('Birth preparation','Record preferences to discuss with your care team. Plans can change as care needs change.')+`<div class="grid">${card('Your birth preferences',form('birthForm',`${['Birth setting','Support person','Comfort and pain relief','Communication preferences','After-birth preferences'].map((label,i)=>`<p><label for="plan${i}">${label}</label><textarea id="plan${i}" name="plan${i}" maxlength="2000">${esc(p['plan'+i])}</textarea></p>`).join('')}`,'Save birth plan')+'<p><button class="secondary" id="birthDownload">Download birth plan</button></p>')}${card('Hospital bag checklist',`<p class="muted">${state.bag.filter(x=>x.done).length} of ${state.bag.length} packed · adapt to your hospital’s advice</p>`+state.bag.map(x=>`<div class="row"><label class="check"><input type="checkbox" data-bag="${x.id}" ${x.done?'checked':''}>${esc(x.text)}</label><button class="danger" data-delete="bag" data-id="${x.id}">Remove</button></div>`).join('')+form('bagForm',`<p>${field('text','Add your own item','text','','required maxlength="150"')}</p>`,'Add item'))}</div>`};
const foodSource='https://www.nhs.uk/pregnancy/keeping-well/foods-to-avoid/';const foodItems=[['Cheese / dairy','Check preparation','Choose pasteurised dairy. Mould-ripened soft and blue cheeses need thorough cooking.'],['Meat','Cook thoroughly','Avoid raw meat and liver. Cook cured meats until hot.'],['Eggs','Check source and cooking','Fully cook eggs without UK safety certification; regional standards differ.'],['Fish / sushi','Check type and preparation','Avoid raw fish, raw shellfish, shark, swordfish and marlin. Cook smoked fish thoroughly.'],['Caffeine / coffee / tea','Limit intake','NHS advises no more than 200 mg daily, counting all sources.'],['Alcohol','Avoid','Avoid alcohol during pregnancy.'],['Fruit / vegetables','Wash thoroughly','Wash produce and remove soil before eating.']];
function foodResults(q=''){let found=foodItems.filter(x=>x.join(' ').toLowerCase().includes(q.toLowerCase()));return found.map(x=>`<div class="row"><div><h3>${x[0]}</h3><span class="tag">${x[1]}</span><p>${x[2]}</p><a href="${foodSource}" target="_blank" rel="noopener">NHS guidance</a></div></div>`).join('')||empty('No reviewed entry for that search. Absence is not evidence of safety. Ask a clinician or pharmacist.');}
renderers.food=()=>heading('Food & safety','A small, searchable reference. Preparation, quantity, and individual circumstances matter.')+`<div class="warning">Medicines and herbs need individual review by your clinician or pharmacist. Do not start or stop a prescribed medicine based on this lookup.</div><div class="grid">${card('Food guidance',`<label for="foodSearch">Search foods or drinks</label><input id="foodSearch" type="search" placeholder="Try eggs, fish, coffee…"><div id="foodResults">${foodResults()}</div><small>NHS guidance · checked 10 October 2026 · follow local clinical advice</small>`)}${card('Medicines, herbs & activities',`<p>For medicines and herbal products, ask your clinician or pharmacist about your exact product and circumstances.</p><p><a href="https://www.nhs.uk/pregnancy/keeping-well/medicines/" target="_blank" rel="noopener">Medicines and herbal remedies · NHS</a></p><p><a href="https://www.nhs.uk/pregnancy/keeping-well/exercise/" target="_blank" rel="noopener">Exercise in pregnancy · NHS</a></p><p>No universal safety score is assigned.</p>`)}</div>`;
const movementSource='https://www.nhs.uk/pregnancy/keeping-well/your-babys-movements/';
renderers.movement=()=>{ensureExtras();return heading('Movement journal','Optional observations of your baby’s usual movement pattern.')+`<div class="warning">If movements decrease, stop, or change from the usual pattern, contact your maternity unit immediately. Do not wait for a count or tomorrow. There is no universal daily movement target. <a href="${movementSource}" target="_blank" rel="noopener">NHS guidance</a></div><div class="grid">${card('Record an observation',`<p>Use this to keep notes, not to assess your baby’s wellbeing.</p><button id="movementTap">Log a movement now</button><p class="muted">Each tap saves a timestamp. There is no pass/fail threshold.</p>`+form('movementNoteForm','<p><label for="movementNote">Pattern / observation</label><textarea id="movementNote" name="note" required maxlength="2000"></textarea></p>','Save observation'))}${card('Your observations',state.movements.slice().reverse().slice(0,50).map(x=>`<div class="row"><div><b>${esc(new Date(x.at).toLocaleString())}</b><p>${esc(x.note)}</p></div><button class="danger" data-delete="movements" data-id="${x.id}">Delete</button></div>`).join('')||empty('No observations recorded.'))}</div>`};
function elapsed(ms){return `${Math.floor(ms/60000)}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}`}
renderers.contractions=()=>{ensureExtras();return heading('Contraction timer','Record duration and spacing. This timer cannot determine whether you are in labour.')+`<div class="warning">Contact your maternity unit if you think labour has started or you are worried. Seek urgent advice for bleeding, waters breaking, reduced movements, or possible labour before 37 weeks. <a href="https://www.nhs.uk/pregnancy/labour-and-birth/signs-that-labour-has-begun/" target="_blank" rel="noopener">NHS guidance</a></div><div class="grid">${card('Current contraction',`<div class="big" id="timerDisplay">${state.activeContraction?elapsed(Date.now()-state.activeContraction):'0:00'}</div><button id="toggleContraction">${state.activeContraction?'Stop and save':'Start contraction'}</button><p class="muted">Uses timestamps, so elapsed time survives navigation and reloads. No automatic labour diagnosis.</p>`)}${card('Recorded contractions',state.contractions.slice().reverse().map(x=>`<div class="row"><div><b>${esc(new Date(x.start).toLocaleString())}</b><p class="muted">Duration ${elapsed(x.end-x.start)} · Start-to-start interval ${x.interval===null?'—':elapsed(x.interval)}</p></div><button class="danger" data-delete="contractions" data-id="${x.id}">Delete</button></div>`).join('')||empty('No completed contractions.'))}</div>`};
renderers.postpartum=()=>{ensureExtras();return heading('After birth','Continue your journal without losing pregnancy records.')+`<div class="grid">${card('Your transition',form('postProfileForm',`${field('birthDate','Baby’s birth date','date',state.birthDate||'','required max="'+today()+'"')}<p class="muted">Saving switches to postpartum mode. You can switch back in Profile.</p>`,'Save birth date')+(state.birthDate?`<p>${Math.max(0,dayNumber(today())-dayNumber(state.birthDate))} days since birth</p>`:''))}${card('Daily recovery note',form('postLogForm',`<div class="grid">${field('day','Date','date',today(),'required max="'+today()+'"')}${selectField('mood','Mood',['Okay','Good','Low','Anxious','Mixed'])}${field('sleep','Sleep · hours','number','','min="0" max="24" step="0.1"')}</div><p><label for="recovery">Recovery / wellbeing notes</label><textarea name="recovery" id="recovery" maxlength="2000"></textarea></p><p><label for="baby">Baby feeding / nappies / sleep notes</label><textarea name="baby" id="baby" maxlength="2000"></textarea></p>`,'Save recovery note'))}</div>${card('Your postpartum journal',state.postpartumLogs.slice().reverse().map(x=>`<div class="row"><div><b>${esc(x.day)} · ${esc(x.mood)}</b><p>Sleep ${esc(x.sleep||'—')} h</p><p>${esc(x.recovery)}</p><p>${esc(x.baby)}</p></div><button class="danger" data-delete="postpartumLogs" data-id="${x.id}">Delete</button></div>`).join('')||empty('No recovery notes yet.'))}<p><a href="https://www.nhs.uk/pregnancy/labour-and-birth/your-body/" target="_blank" rel="noopener">Recovery after birth · NHS</a></p>`};
function notifyStatus(){return !('Notification'in window)?'Browser notifications are unsupported.':Notification.permission==='granted'?'Browser permission granted. Alerts still require the app to be open.':`Browser permission: ${Notification.permission}.`}
renderers.reminders=()=>heading('Calendar & alerts','Bring appointment plans and medication schedules into your own calendar.')+`<div class="grid">${card('Calendar downloads','<p>Download an .ics file and import it into Google Calendar, Outlook, or Apple Calendar. Medication events repeat daily; appointment events include a reminder.</p><button id="calendarDownload">Download calendar events</button><p class="muted">One-way export. Changes here do not update imported events. Set or verify alerts in your calendar app. Appointment requests remain unconfirmed.</p>')}${card('Browser notifications',`<p>${notifyStatus()}</p><div class="actions"><button id="enableNotifications">Enable open-app notifications</button><button id="testNotification" class="secondary">Test notification</button><button id="disableNotifications" class="secondary">Disable app alerts</button></div><p class="muted">Status: ${state.notificationEnabled?'enabled':'disabled'}. Browser/device support varies. Reliable background push is not connected; use calendar alerts as an alternative.</p>`)}</div>`;
const oldRisk=renderers.risk;renderers.risk=()=>state.mode==='postpartum'?heading('Pregnancy model unavailable after birth','The training data does not support postpartum risk prediction.')+card('Your history is preserved','<a class="button" href="#trends">View pregnancy measurements</a>'):oldRisk();
function icsEscape(s){return String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
function calendar(){let ev=[];let stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z');const dt=(day,time)=>day.replaceAll('-','')+'T'+time.replace(':','')+'00';function event(id,start,title,description,repeat=false){return ['BEGIN:VEVENT','UID:'+id+'@bloom.local','DTSTAMP:'+stamp,'DTSTART:'+start,'DURATION:PT30M','SUMMARY:'+icsEscape(title),'DESCRIPTION:'+icsEscape(description),...(repeat?['RRULE:FREQ=DAILY']:[]),'BEGIN:VALARM','TRIGGER:-PT15M','ACTION:DISPLAY','DESCRIPTION:Reminder','END:VALARM','END:VEVENT'].join('\r\n')};state.appointments.forEach(a=>ev.push(event(a.id,dt(a.day,a.time),'Appointment plan: '+a.clinic,'Unconfirmed local plan. Contact clinic directly. '+a.reason)));state.meds.forEach(m=>ev.push(event(m.id,dt(today(),m.time),'Medication reminder','Follow your prescribed schedule: '+m.name+' '+m.dose,true)));if(!ev.length){notify('Add an appointment or medication schedule first.');return}download('bloom-calendar.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Bloom//Pregnancy companion//EN','CALSCALE:GREGORIAN',...ev,'END:VCALENDAR',''].join('\r\n'),'text/calendar')}
function browserAlert(){if(!state.notificationEnabled||!('Notification'in window)||Notification.permission!=='granted')return;try{new Notification('Bloom reminder',{body:'A scheduled reminder is due. Open Bloom to view it.',tag:'bloom-reminder'})}catch{navigator.serviceWorker.ready.then(r=>r.showNotification('Bloom reminder',{body:'A scheduled reminder is due. Open Bloom to view it.'})).catch(()=>{})}}
const extraSubmit=new Set(['wellnessForm','birthForm','bagForm','movementNoteForm','postProfileForm','postLogForm']);
document.addEventListener('submit',e=>{if(!extraSubmit.has(e.target.id))return;e.preventDefault();ensureExtras();let f=e.target,v=vals(f),id=crypto.randomUUID();if(f.id==='wellnessForm'){state.wellness=state.wellness.filter(x=>x.day!==v.day);state.wellness.push({...v,id})}if(f.id==='birthForm')state.birthPlan=v;if(f.id==='bagForm')state.bag.push({...v,id,done:false});if(f.id==='movementNoteForm')state.movements.push({...v,id,at:new Date().toISOString()});if(f.id==='postProfileForm'){state.birthDate=v.birthDate;state.mode='postpartum'}if(f.id==='postLogForm')state.postpartumLogs.push({...v,id});save();render();notify('Changes queued. Check the account save status.')});
document.addEventListener('input',e=>{if(e.target.id==='foodSearch')$('#foodResults').innerHTML=foodResults(e.target.value)});
document.addEventListener('change',e=>{if(e.target.id==='growthWeek'){selectedWeek=Number(e.target.value);$('#growthDetail').innerHTML=growthCard(selectedWeek)}if(e.target.dataset.bag){state.bag.find(x=>x.id===e.target.dataset.bag).done=e.target.checked;save();render()}});
document.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;ensureExtras();if(b.dataset.mode){state.mode=b.dataset.mode;save();render()}if(b.id==='movementTap'){state.movements.push({id:crypto.randomUUID(),at:new Date().toISOString(),note:'Movement observed'});save();render();notify('Movement observation saved.')}if(b.id==='toggleContraction'){let now=Date.now();if(state.activeContraction){let previous=state.contractions.at(-1);state.contractions.push({id:crypto.randomUUID(),start:state.activeContraction,end:now,interval:previous?state.activeContraction-previous.start:null});delete state.activeContraction}else state.activeContraction=now;save();render()}if(b.id==='calendarDownload')calendar();if(b.id==='birthDownload')download('bloom-birth-plan.txt','Birth preferences — discuss with care team\n\n'+['Birth setting','Support person','Comfort and pain relief','Communication preferences','After-birth preferences'].map((s,i)=>s+':\n'+(state.birthPlan['plan'+i]||'Not entered')).join('\n\n'),'text/plain');if(b.id==='enableNotifications'){if(!('Notification'in window)){notify('Notifications are unsupported in this browser. Use calendar downloads.');return}let p=await Notification.requestPermission();state.notificationEnabled=p==='granted';save();render();notify(p==='granted'?'Open-app alerts enabled. Background push is not connected.':'Permission not granted. Calendar downloads remain available.')}if(b.id==='testNotification'){if(!state.notificationEnabled){notify('Enable notifications first.');return}browserAlert();notify('Notification requested; delivery depends on your browser and device.')}if(b.id==='disableNotifications'){state.notificationEnabled=false;save();render();notify('App alerts disabled. Browser permission is managed in browser settings.')}});
setInterval(()=>{if($('#timerDisplay')&&state.activeContraction)$('#timerDisplay').textContent=elapsed(Date.now()-state.activeContraction)},1000);
let sentAlerts=new Set();setInterval(()=>{if(typeof accountUser==='undefined'||!accountUser)return;ensureExtras();let now=new Date(),day=today(),time=now.toTimeString().slice(0,5);state.meds.forEach(m=>{let key=day+m.id;if(m.time===time&&!sentAlerts.has(key)&&!m.taken?.includes(day)){sentAlerts.add(key);browserAlert()}});state.appointments.forEach(a=>{let mins=(new Date(a.day+'T'+a.time)-now)/60000,key=day+a.id;if(mins>=0&&mins<=15&&!sentAlerts.has(key)){sentAlerts.add(key);notify('Your planned appointment is within 15 minutes. Confirm with the clinic.');browserAlert()}})},15000);
function extraReportHtml(){ensureExtras();let labels=['Birth setting','Support person','Comfort and pain relief','Communication preferences','After-birth preferences'];return '<h2>Daily wellbeing</h2>'+state.wellness.map(x=>`<p>${esc(x.day)} · ${esc(x.mood)} · Sleep ${esc(x.sleep||'—')} h · Weight ${esc(x.weight||'—')} kg · Water ${esc(x.water||'—')} mL<br>${esc(x.note)}</p>`).join('')+'<h2>Birth preferences</h2>'+labels.map((s,i)=>`<p><b>${s}</b>: ${esc(state.birthPlan['plan'+i]||'Not entered')}</p>`).join('')+'<h2>Movement observations</h2>'+state.movements.map(x=>`<p>${esc(new Date(x.at).toLocaleString())}: ${esc(x.note)}</p>`).join('')+'<h2>Contractions (not a labour diagnosis)</h2>'+state.contractions.map(x=>`<p>${esc(new Date(x.start).toLocaleString())} · Duration ${elapsed(x.end-x.start)} · Interval ${x.interval===null?'—':elapsed(x.interval)}</p>`).join('')+'<h2>Postpartum journal</h2>'+state.postpartumLogs.map(x=>`<p>${esc(x.day)} · ${esc(x.mood)} · Sleep ${esc(x.sleep||'—')} h<br>${esc(x.recovery)}<br>${esc(x.baby)}</p>`).join('')}
fetch('weeks.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(x=>{weekly=x;if(location.hash==='#growth')render()}).catch(()=>notify('Weekly guide unavailable. Revisit when online.'));render();
